# Kaggle kernel runner, generated by scripts/kaggle/launch.py from runner_template.py.
# Do not edit the generated copy; edit the template and relaunch.
#
# Steps: locate the code snapshot from the private dataset -> /kaggle/working/repo,
# verify its COMMIT, install mamba-ssm + causal-conv1d (prebuilt wheel matching
# torch/CUDA/python/cxx11abi, else `pip install --no-build-isolation`), install repo
# deps, run the command, tee everything to /kaggle/working/output/run.log and write
# /kaggle/working/output/kaggle_env.json.
import datetime
import glob
import json
import os
import platform
import re
import shutil
import subprocess
import sys
import tarfile
import time
import traceback
import urllib.request

CMD = "__ABR_CMD__"
EXPECTED_COMMIT = "__ABR_COMMIT__"
KERNEL_URL = "__ABR_KERNEL_URL__"
KERNEL_REF = "__ABR_KERNEL_REF__"
DATASET_REF = "__ABR_DATASET_REF__"
DATASET_VERSION = "__ABR_DATASET_VERSION__"
GPU_REQUESTED = "__ABR_GPU_REQUESTED__"
RESUME_SOURCES = "__ABR_RESUME_SOURCES__"

# Overridable only for local testing of the runner itself.
WORK = os.environ.get("ABR_RUNNER_WORK", "/kaggle/working")
REPO = os.path.join(WORK, "repo")
OUT = os.path.join(WORK, "output")
INPUT = os.environ.get("ABR_RUNNER_INPUT", "/kaggle/input")
SKIP_INSTALL = os.environ.get("ABR_RUNNER_SKIP_INSTALL") == "1"
os.makedirs(OUT, exist_ok=True)
LOG_PATH = os.path.join(OUT, "run.log")
ENV_PATH = os.path.join(OUT, "kaggle_env.json")
_log = open(LOG_PATH, "a", buffering=1)


def utcnow():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def log(msg):
    line = f"[runner {utcnow()}] {msg}"
    print(line, flush=True)
    _log.write(line + "\n")


def sh(cmd, cwd=None, env=None, check=False):
    """Run a shell command, streaming combined output to stdout and run.log."""
    log(f"$ {cmd}")
    p = subprocess.Popen(cmd, shell=True, cwd=cwd, env=env, stdout=subprocess.PIPE,
                         stderr=subprocess.STDOUT, text=True, bufsize=1, executable="/bin/bash")
    out = []
    for line in p.stdout:
        sys.stdout.write(line)
        _log.write(line)
        out.append(line)
    rc = p.wait()
    log(f"exit {rc}")
    if check and rc != 0:
        raise RuntimeError(f"command failed ({rc}): {cmd}")
    return rc, "".join(out)


ENV = {
    "started_utc": utcnow(),
    "kernel_ref": KERNEL_REF,
    "kernel_url": KERNEL_URL,
    "dataset_ref": DATASET_REF,
    "dataset_version": DATASET_VERSION,
    "commit_expected": EXPECTED_COMMIT,
    "gpu_requested": GPU_REQUESTED,
    "cmd": CMD,
    "python": sys.version,
    "platform": platform.platform(),
    "kaggle_env_vars": {k: v for k, v in os.environ.items()
                        if k.startswith("KAGGLE_") and "TOKEN" not in k and "KEY" not in k
                        and "SECRET" not in k},
}


def save_env():
    with open(ENV_PATH, "w") as f:
        json.dump(ENV, f, indent=2, sort_keys=True)


# ---------------------------------------------------------------------------------
# 1. Code snapshot
# ---------------------------------------------------------------------------------
def locate_and_copy_code():
    if os.path.exists(REPO):
        shutil.rmtree(REPO)
    archives = sorted(glob.glob(os.path.join(INPUT, "**", "abr-code.tar.gz"), recursive=True))
    archives = [a for a in archives if os.path.isfile(a)]
    if archives:
        log(f"extracting {archives[0]}")
        tmp = os.path.join(WORK, "_code_extract")
        shutil.rmtree(tmp, ignore_errors=True)
        with tarfile.open(archives[0]) as t:
            try:
                t.extractall(tmp, filter="data")
            except TypeError:  # python < 3.10.12
                t.extractall(tmp)
        shutil.move(os.path.join(tmp, "repo"), REPO)
        shutil.rmtree(tmp, ignore_errors=True)
        ENV["code_source"] = archives[0]
    else:
        # Kaggle may auto-extract archives: look for an extracted COMMIT file.
        commits = sorted(glob.glob(os.path.join(INPUT, "**", "repo", "COMMIT"), recursive=True))
        if not commits:
            listing = sh(f"find {INPUT} -maxdepth 4 | head -100")[1]
            raise RuntimeError(f"code snapshot not found under {INPUT}:\n{listing}")
        src = os.path.dirname(commits[0])
        log(f"copying extracted snapshot {src}")
        shutil.copytree(src, REPO)
        ENV["code_source"] = src
    commit = open(os.path.join(REPO, "COMMIT")).read().strip()
    ENV["commit"] = commit
    if commit != EXPECTED_COMMIT:
        raise RuntimeError(f"code snapshot commit {commit} != expected {EXPECTED_COMMIT}; "
                           "the dataset version attached to this kernel is not the one launched")
    snap = os.path.join(REPO, "git_snapshot.json")
    ENV["git_snapshot_present"] = os.path.exists(snap)
    if ENV["git_snapshot_present"]:
        import hashlib
        ENV["git_snapshot_sha256"] = hashlib.sha256(open(snap, "rb").read()).hexdigest()
    log(f"code snapshot at {REPO}, commit {commit}, git_snapshot.json present: "
        f"{ENV['git_snapshot_present']}")


# ---------------------------------------------------------------------------------
# 2. GPU / torch info
# ---------------------------------------------------------------------------------
def gpu_info():
    rc, out = sh("nvidia-smi --query-gpu=name,driver_version,memory.total,compute_cap "
                 "--format=csv,noheader")
    if rc != 0 or not out.strip():
        ENV["no_gpu"] = True
        log("NO GPU visible (nvidia-smi failed). If the kernel was pushed with enable_gpu, "
            "Kaggle may have refused the accelerator: the owner must phone-verify the account "
            "at https://www.kaggle.com/settings.")
        return
    fields = [f.strip() for f in out.strip().splitlines()[0].split(",")]
    ENV["gpu_count"] = len(out.strip().splitlines())
    ENV["gpu_name"], ENV["driver_version"] = fields[0], fields[1]
    ENV["gpu_memory_total"] = fields[2] if len(fields) > 2 else None
    ENV["gpu_compute_cap"] = fields[3] if len(fields) > 3 else None
    rc, smi = sh("nvidia-smi")
    m = re.search(r"CUDA Version:\s*([\d.]+)", smi)
    ENV["driver_cuda_version"] = m.group(1) if m else None


def torch_info():
    import torch
    ENV["torch"] = torch.__version__
    ENV["torch_cuda"] = torch.version.cuda
    ENV["cudnn"] = torch.backends.cudnn.version() if torch.backends.cudnn.is_available() else None
    ENV["cxx11abi"] = bool(torch._C._GLIBCXX_USE_CXX11_ABI)
    ENV["cuda_available"] = torch.cuda.is_available()
    if torch.cuda.is_available():
        ENV["torch_gpu_name"] = torch.cuda.get_device_name(0)
        ENV["torch_compute_capability"] = list(torch.cuda.get_device_capability(0))
        ENV["torch_arch_list"] = torch.cuda.get_arch_list()
    return torch


# ---------------------------------------------------------------------------------
# 3. mamba-ssm / causal-conv1d install
# ---------------------------------------------------------------------------------
_WHEEL_RE = re.compile(r"\+cu(\d+)torch(\d+\.\d+)cxx11abi(TRUE|FALSE)-(cp\d+)-(cp\d+)-linux_x86_64\.whl$")


def find_wheel(repo, cuda_major, torch_mm, abi, cp):
    """Newest GitHub release asset matching cu<major>*, torch major.minor, ABI and python."""
    url = f"https://api.github.com/repos/{repo}/releases?per_page=40"
    req = urllib.request.Request(url, headers={"Accept": "application/vnd.github+json",
                                               "User-Agent": "abr-kaggle-runner"})
    with urllib.request.urlopen(req, timeout=60) as r:
        releases = json.load(r)
    for rel in releases:  # newest first
        if rel.get("draft") or rel.get("prerelease"):
            continue
        best = None
        for asset in rel.get("assets", []):
            m = _WHEEL_RE.search(asset["name"])
            if not m:
                continue
            cu, tv, ab, py, _ = m.groups()
            if cu.startswith(str(cuda_major)) and tv == torch_mm and ab == abi and py == cp:
                # prefer the highest cuda minor <= runtime (cu12 > cu122 naming both ok)
                if best is None or cu > best[0]:
                    best = (cu, asset["browser_download_url"], rel["tag_name"])
        if best:
            return {"url": best[1], "tag": best[2], "asset_cuda": best[0]}
    return None


def install_mamba(torch):
    t0 = time.time()
    info = {}
    torch_mm = ".".join(torch.__version__.split("+")[0].split(".")[:2])
    cuda_major = (torch.version.cuda or "12").split(".")[0]
    abi = "TRUE" if torch._C._GLIBCXX_USE_CXX11_ABI else "FALSE"
    cp = f"cp{sys.version_info.major}{sys.version_info.minor}"
    info["match_key"] = {"torch": torch_mm, "cuda_major": cuda_major, "cxx11abi": abi, "python": cp}
    wheels = {}
    for pkg, repo in (("causal_conv1d", "Dao-AILab/causal-conv1d"), ("mamba_ssm", "state-spaces/mamba")):
        try:
            wheels[pkg] = find_wheel(repo, cuda_major, torch_mm, abi, cp)
        except Exception as e:
            log(f"wheel lookup for {pkg} failed: {e}")
            wheels[pkg] = None
    info["wheels"] = wheels
    if all(wheels.values()):
        info["method"] = "prebuilt_wheels"
        rc, _ = sh(f"pip install --no-deps {wheels['causal_conv1d']['url']} {wheels['mamba_ssm']['url']}")
        if rc != 0:
            info["method"] = "prebuilt_wheels_failed->pip_no_build_isolation"
    else:
        info["method"] = "pip_no_build_isolation"
    sh("pip install einops ninja packaging")
    if info["method"] != "prebuilt_wheels":
        # The packages' setup.py first tries to download the matching wheel itself and
        # only compiles CUDA sources if none exists (slow: tens of minutes).
        sh("pip install --no-build-isolation causal-conv1d", env=dict(os.environ, MAX_JOBS="4"))
        sh("pip install --no-build-isolation mamba-ssm", env=dict(os.environ, MAX_JOBS="4"))
    info["install_seconds"] = round(time.time() - t0, 1)
    return info


def installed_versions():
    code = ("import json,importlib.metadata as m\n"
            "out={}\n"
            "for p in ['torch','triton','mamba-ssm','causal-conv1d','transformers','datasets','wandb','einops','numpy']:\n"
            "    try: out[p]=m.version(p)\n"
            "    except Exception as e: out[p]=None\n"
            "for mod in ['mamba_ssm','causal_conv1d']:\n"
            "    try:\n"
            "        x=__import__(mod); out[mod+'_import']='ok '+getattr(x,'__version__','?')\n"
            "    except Exception as e: out[mod+'_import']='FAILED: '+repr(e)[:400]\n"
            "print('VERSIONS_JSON='+json.dumps(out))\n")
    path = os.path.join(WORK, "_versions.py")
    with open(path, "w") as f:
        f.write(code)
    rc, out = sh(f"{sys.executable} {path}")
    os.remove(path)
    for line in out.splitlines():
        if line.startswith("VERSIONS_JSON="):
            return json.loads(line[len("VERSIONS_JSON="):])
    return {"error": out[-2000:]}


# ---------------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------------
def main():
    rc = 1
    save_env()
    try:
        locate_and_copy_code()
        save_env()
        gpu_info()
        torch = torch_info()
        save_env()
        try:
            if SKIP_INSTALL:
                raise RuntimeError("ABR_RUNNER_SKIP_INSTALL=1 (local runner test)")
            ENV["mamba_install"] = install_mamba(torch)
        except Exception:
            ENV["mamba_install"] = {"error": traceback.format_exc()}
            log(ENV["mamba_install"]["error"])
        if not SKIP_INSTALL:
            sh('pip install "datasets" "transformers<5" "wandb"')
        ENV["versions"] = installed_versions()
        ENV["mamba_ssm"] = ENV["versions"].get("mamba-ssm")
        ENV["causal_conv1d"] = ENV["versions"].get("causal-conv1d")
        sh(f"{sys.executable} -m pip freeze > " + os.path.join(OUT, "pip_freeze.txt"))
        save_env()

        env = dict(os.environ)
        env.update({
            "WANDB_MODE": "offline",
            "WANDB_DIR": os.path.join(OUT, "wandb"),
            "KAGGLE_KERNEL_URL": KERNEL_URL,
            "KAGGLE_DATASET_VERSION": str(DATASET_VERSION),
            "CODE_COMMIT": ENV["commit"],
            "ABR_OUTPUT_DIR": OUT,
            "ABR_RESUME_DIRS": ":".join(os.path.join(INPUT, s.split("/")[-1]) for s in RESUME_SOURCES),
            "PYTHONUNBUFFERED": "1",
        })
        # Kaggle does not tell a running kernel its own version number; the launcher
        # records the real one in results/kaggle/<name>/launch.json. Pass one through
        # only if the platform provides it.
        kv = os.environ.get("KAGGLE_KERNEL_VERSION") or os.environ.get("KAGGLE_KERNEL_VERSION_NUMBER")
        if kv:
            env["KAGGLE_KERNEL_VERSION"] = kv
        ENV["kaggle_kernel_version_env"] = kv
        os.makedirs(env["WANDB_DIR"], exist_ok=True)
        ENV["cmd_started_utc"] = utcnow()
        save_env()
        log(f"running command in {REPO}: {CMD}")
        rc, _ = sh(CMD, cwd=REPO, env=env)
        ENV["cmd_exit_code"] = rc
    except Exception:
        ENV["runner_error"] = traceback.format_exc()
        log(ENV["runner_error"])
        rc = 1
    finally:
        ENV["finished_utc"] = utcnow()
        save_env()
        # The exact code is preserved in the dataset version; don't duplicate it in outputs.
        shutil.rmtree(REPO, ignore_errors=True)
        log(f"done, exit code {rc}")
        _log.close()
    sys.exit(rc)


if __name__ == "__main__":
    main()
